// The queue. README.md has the contract.

import { CancelledError, TaskTimeoutError } from './errors.js';

function checkConcurrency(value) {
  if (!Number.isInteger(value) || value < 1) {
    throw new RangeError('concurrency must be a positive integer, got ' + value);
  }
  return value;
}

export class JobQueue {
  constructor({ concurrency = 1 } = {}) {
    this._concurrency = checkConcurrency(concurrency);
    this._running = 0;
    this._waiting = [];
    this._paused = false;
    this._idle = [];
    this._scheduling = false;
  }

  get concurrency() {
    return this._concurrency;
  }

  set concurrency(value) {
    this._concurrency = checkConcurrency(value);
    this._schedule();
  }

  get pending() {
    return this._running;
  }

  get size() {
    return this._waiting.length;
  }

  get isPaused() {
    return this._paused;
  }

  add(fn, { priority = 0, timeout = 0, retries = 0, retryDelay = 0 } = {}) {
    return new Promise((resolve, reject) => {
      const job = { fn, priority, timeout, retries, retryDelay, resolve, reject };
      // Highest priority first; equal priorities keep the order they were added.
      const { _waiting: waiting } = this;
      let index = waiting.length;
      while (index > 0 && waiting[index - 1].priority < priority) index -= 1;
      waiting.splice(index, 0, job);
      this._schedule();
    });
  }

  _schedule() {
    // Jobs may settle synchronously and call back in; the outermost loop keeps going.
    if (this._scheduling) return;
    this._scheduling = true;
    try {
      while (!this._paused && this._running < this._concurrency && this._waiting.length > 0) {
        const job = this._waiting.shift();
        this._running += 1;
        this._attempt(job, 1);
      }
      if (this._running === 0 && this._waiting.length === 0) {
        for (const resolve of this._idle.splice(0)) resolve();
      }
    } finally {
      this._scheduling = false;
    }
  }

  _attempt(job, attempt) {
    const controller = new AbortController();
    let finished = false;
    let timer = null;

    const settle = (ok, value) => {
      if (finished) return;
      finished = true;
      if (timer !== null) clearTimeout(timer);
      timer = null;
      if (ok) {
        this._running -= 1;
        job.resolve(value);
        this._schedule();
        return;
      }
      if (attempt <= job.retries) {
        // The job keeps its slot; only the wait before the next attempt is timed.
        timer = setTimeout(() => {
          timer = null;
          this._attempt(job, attempt + 1);
        }, job.retryDelay);
        return;
      }
      this._running -= 1;
      job.reject(value);
      this._schedule();
    };

    if (job.timeout > 0) {
      timer = setTimeout(() => {
        timer = null;
        controller.abort();
        settle(false, new TaskTimeoutError(job.timeout));
      }, job.timeout);
    }

    let outcome;
    try {
      outcome = job.fn({ signal: controller.signal, attempt });
    } catch (error) {
      settle(false, error);
      return;
    }

    Promise.resolve(outcome).then(
      (value) => settle(true, value),
      (error) => settle(false, error),
    );
  }

  pause() {
    this._paused = true;
  }

  resume() {
    this._paused = false;
    this._schedule();
  }

  clear() {
    const { _waiting: dropped } = this;
    this._waiting = [];
    for (const job of dropped) job.reject(new CancelledError());
    this._schedule();
    return dropped.length;
  }

  onIdle() {
    if (this._running === 0 && this._waiting.length === 0) return Promise.resolve();
    return new Promise((resolve) => this._idle.push(resolve));
  }
}

import assert from 'node:assert/strict';
import { setTimeout as sleep } from 'node:timers/promises';

import { JobQueue, TaskTimeoutError, CancelledError } from './src/index.js';

for (const bad of [0, -1, 1.5, '2', Infinity, NaN, null]) {
  assert.throws(() => new JobQueue({ concurrency: bad }), RangeError, 'ctor ' + String(bad));
}
assert.equal(new JobQueue().concurrency, 1);
assert.equal(new JobQueue({}).concurrency, 1);

{
  const q = new JobQueue({ concurrency: 2 });
  q.concurrency = 3;
  assert.equal(q.concurrency, 3);
  assert.throws(() => { q.concurrency = 0; }, RangeError);
  assert.throws(() => { q.concurrency = 2.5; }, RangeError);
  assert.equal(q.concurrency, 3, 'a rejected value changes nothing');
}

{
  const q = new JobQueue({ concurrency: 1 });
  let calls = 0;
  const gate = sleep(15);
  const jobs = Array.from({ length: 5 }, () => q.add(async () => { calls += 1; await gate; return 'done'; }));
  assert.equal(calls, 1, 'a job starts before add returns');
  q.concurrency = 5;
  assert.equal(calls, 5, 'raising concurrency starts waiting jobs at once');
  q.concurrency = 1;
  await Promise.all(jobs);
  assert.equal(q.pending, 0);
  assert.equal(q.size, 0);
}

{
  const q = new JobQueue({ concurrency: 1 });
  q.pause();
  const order = [];
  const mk = (name) => () => { order.push(name); };
  const ps = [
    q.add(mk('a0'), { priority: 0 }),
    q.add(mk('b5'), { priority: 5 }),
    q.add(mk('c0'), { priority: 0 }),
    q.add(mk('d5'), { priority: 5 }),
    q.add(mk('e3'), { priority: 3 }),
  ];
  assert.equal(q.size, 5);
  assert.equal(q.pending, 0);
  assert.equal(q.isPaused, true);
  let idle = false;
  q.onIdle().then(() => { idle = true; });
  await sleep(10);
  assert.equal(idle, false, 'a paused queue with waiting jobs is not idle');
  q.resume();
  await Promise.all(ps);
  assert.deepEqual(order, ['b5', 'd5', 'e3', 'a0', 'c0']);
  await q.onIdle();
  assert.equal(idle, true);
}

{
  const q = new JobQueue({ concurrency: 1 });
  assert.equal(await q.add(() => 42), 42);
  assert.deepEqual(await q.add(async () => ({ a: 1 })), { a: 1 });
  await assert.rejects(q.add(() => { throw new Error('sync boom'); }), /sync boom/);
  await assert.rejects(q.add(async () => { throw new Error('async boom'); }), /async boom/);
  assert.equal(await q.add(() => 'next'), 'next');
  assert.equal(q.pending, 0);
}

{
  const q = new JobQueue({ concurrency: 1 });
  const seen = [];
  const signals = [];
  const starts = [];
  const result = await q.add(({ signal, attempt }) => {
    seen.push(attempt);
    signals.push(signal);
    starts.push(Date.now());
    if (attempt < 3) throw new Error('attempt ' + attempt + ' failed');
    return 'done';
  }, { retries: 2, retryDelay: 20 });
  assert.equal(result, 'done');
  assert.deepEqual(seen, [1, 2, 3]);
  assert.ok(signals[0] instanceof AbortSignal);
  assert.notEqual(signals[0], signals[1], 'a retry gets a fresh signal');
  assert.notEqual(signals[1], signals[2], 'a retry gets a fresh signal');
  assert.ok(starts[1] - starts[0] >= 18, 'a retry waits retryDelay');
  assert.equal(q.pending, 0);
}

{
  const q = new JobQueue({ concurrency: 1 });
  let attempts = 0;
  const p = q.add(async ({ attempt }) => {
    attempts = attempt;
    if (attempt < 3) throw new Error('still failing');
    return 'ok ' + attempt;
  }, { retries: 5 });
  assert.equal(await p, 'ok 3');
  assert.equal(attempts, 3);
}

{
  const q = new JobQueue({ concurrency: 1 });
  const p = q.add(() => { throw new Error('nope'); }, { retries: 1, retryDelay: 40 });
  await sleep(10);
  assert.equal(q.pending, 1, 'a job waiting for its retry is running');
  assert.equal(q.size, 0);
  await assert.rejects(p, /nope/);
  assert.equal(q.pending, 0);
}

{
  const q = new JobQueue({ concurrency: 1 });
  let aborted = false;
  const started = Date.now();
  await assert.rejects(
    q.add(({ signal }) => {
      signal.addEventListener('abort', () => { aborted = true; });
      return sleep(300);
    }, { timeout: 20 }),
    { name: 'TaskTimeoutError' },
  );
  assert.ok(aborted, 'the timed out attempt signal is aborted');
  assert.ok(Date.now() - started < 200, 'a timeout does not wait for fn');
  assert.equal(await q.add(() => 'slot back'), 'slot back');

  const q2 = new JobQueue({ concurrency: 1 });
  let last = 0;
  await assert.rejects(
    q2.add(({ attempt }) => { last = attempt; return sleep(200); }, { timeout: 10, retries: 2, retryDelay: 5 }),
    TaskTimeoutError,
  );
  assert.equal(last, 3);
  assert.equal(q2.pending, 0);
}

{
  const q = new JobQueue({ concurrency: 1 });
  const running = q.add(() => sleep(20).then(() => 'ran'));
  const a = q.add(() => 'a');
  const b = q.add(() => 'b');
  assert.equal(q.clear(), 2);
  await assert.rejects(a, CancelledError);
  await assert.rejects(b, { name: 'CancelledError' });
  assert.equal(q.size, 0);
  assert.equal(await running, 'ran');
  assert.equal(q.clear(), 0);

  const q2 = new JobQueue({ concurrency: 1 });
  q2.pause();
  const never = q2.add(() => 'never');
  let idle = false;
  q2.onIdle().then(() => { idle = true; });
  await sleep(5);
  assert.equal(idle, false);
  q2.clear();
  await assert.rejects(never, CancelledError);
  await q2.onIdle();
  assert.equal(idle, true);
}

{
  const q = new JobQueue();
  await q.onIdle();
  assert.equal(q.pending, 0);
}

{
  const q = new JobQueue({ concurrency: 2 });
  let running = 0;
  let most = 0;
  const job = async (fail) => {
    running += 1;
    most = Math.max(most, running);
    await sleep(5);
    running -= 1;
    if (fail) throw new Error('boom');
    return 'fine';
  };
  const results = await Promise.allSettled([
    q.add(() => job(true)), q.add(() => job(false)), q.add(() => job(true)), q.add(() => job(false)),
  ]);
  assert.deepEqual(results.map((r) => r.status), ['rejected', 'fulfilled', 'rejected', 'fulfilled']);
  assert.equal(most, 2);
}

console.log('all checks passed');
